<?php
 class InegiEducacionObjetivoService { private const MAX_DESCARGA_BYTES = 67108864; private const CACHE_TTL_SEGUNDOS = 21600; private const MAX_LINEAS_CABECERA = 40; private $enlacesIntercensal2025 = null; public function obtenerPorEstado(string $claveEstado): array { $claveEstado = str_pad(trim($claveEstado), 2, '0', STR_PAD_LEFT); if (!preg_match('/^(0[1-9]|[12][0-9]|3[0-2])$/', $claveEstado)) { return $this->error('La clave del Estado no es válida.'); } $errores = []; foreach ($this->candidatos($claveEstado) as $candidato) { $cache = $this->rutaCache($claveEstado, $candidato['id']); $cacheDatos = $this->leerCache($cache); if ($cacheDatos !== null) { return $cacheDatos; } $resultado = $candidato['tipo'] === 'arcgis' ? $this->consultarArcGis($claveEstado, $candidato) : $this->descargarArchivo($claveEstado, $candidato); if (($resultado['ok'] ?? false) === true) { $this->guardarCache($cache, $resultado); return $resultado; } $mensaje = trim((string)($resultado['mensaje'] ?? '')); if ($mensaje !== '') { $errores[$mensaje] = true; } } $detalle = empty($errores) ? '' : ' ' . implode(' ', array_slice(array_keys($errores), 0, 2)); return $this->error( 'No se encontró una fuente educativa oficial de INEGI compatible con el indicador requerido.' . $detalle ); } private function candidatos(string $claveEstado): array { $candidatos = []; foreach ($this->descubrirIntercensal2025($claveEstado) as $url) { $candidatos[] = [ 'id' => 'EIC2025_' . substr(sha1($url), 0, 10), 'tipo' => 'archivo', 'periodo' => 2025, 'producto' => 'EIC', 'fuente' => 'INEGI - Encuesta Intercensal 2025', 'url' => $url, 'prioridad' => 400 ]; } $decada = (int)(floor((int)date('Y') / 10) * 10); for ($anio = $decada; $anio >= 2030; $anio -= 10) { $candidatos[] = [ 'id' => 'CPV' . $anio, 'tipo' => 'archivo', 'periodo' => $anio, 'producto' => 'CPV', 'fuente' => 'INEGI - Censo de Población y Vivienda ' . $anio . ' (ITER)', 'url' => 'https://www.inegi.org.mx/contenidos/programas/ccpv/' . $anio . '/datosabiertos/i