] ?? null) ); if (!$this->metricasValidas($metricas)) { continue; } return $this->exito($candidato, 'FeatureServer/0', $claveEstado, (string)($r['NOM_ENT'] ?? ''), $metricas); } return $this->error('INEGI respondió, pero no devolvió un total estatal con variables educativas válidas.'); } private function descargarArchivo(string $claveEstado, array $candidato): array { $url = trim((string)$candidato['url']); if (!$this->urlInegi($url) || !function_exists('curl_init')) { return $this->error('La fuente oficial configurada no está disponible.'); } $tmp = tempnam(sys_get_temp_dir(), 'inegi_edu_'); $fp = $tmp !== false ? fopen($tmp, 'wb') : false; if ($tmp === false || $fp === false) { return $this->error('No fue posible preparar la descarga de INEGI.'); } $bytes = 0; $exceso = false; $ch = curl_init(); curl_setopt_array($ch, [ CURLOPT_URL => $url, CURLOPT_FOLLOWLOCATION => true, CURLOPT_MAXREDIRS => 3, CURLOPT_CONNECTTIMEOUT => 10, CURLOPT_TIMEOUT => 60, CURLOPT_SSL_VERIFYPEER => true, CURLOPT_USERAGENT => 'SistemaComercialIMPE/1.0', CURLOPT_HTTPHEADER => ['Accept: application/zip,text/csv,application/octet-stream;q=0.9,*/*;q=0.5'], CURLOPT_WRITEFUNCTION => static function ($curl, $bloque) use ($fp, &$bytes, &$exceso) { $longitud = strlen((string)$bloque); $bytes += $longitud; if ($bytes > self::MAX_DESCARGA_BYTES) { $exceso = true; return 0; } $n = fwrite($fp, (string)$bloque); return $n === false ? 0 : $n; } ]); $ok = curl_exec($ch); $http = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); $tipo = strtolower((string)curl_getinfo($ch, CURLINFO_CONTENT_TYPE)); $error = curl_error($ch); unset($ch); fclose($fp); if ($exceso) { @unlink($tmp); return $this->error('La fuente detectada supera el tamaño máximo permitido para validación automática.'); } if ($ok === false || $error !== '' || $http !== 200) { @unlink($tmp); return $this->error('La fuente ' . (int)$candidato['periodo'] . ' todavía no está disponible o no respondió correctamente.'); } $rutaUrl = (string)parse_url($url, P