g $origen): array { $stream = fopen($ruta, 'rb'); if ($stream === false) { return $this->error('No fue posible leer el CSV oficial de INEGI.'); } $resultado = $this->procesarCsv($stream, $claveEstado, $candidato, $origen); fclose($stream); return $resultado; } private function procesarCsv($stream, string $claveEstado, array $candidato, string $origen): array { $cabecera = $this->buscarCabecera($stream); if ($cabecera === null) { return $this->error('No se localizó una fila de encabezados con ENTIDAD, P_15YMAS y P15SEC_CO.'); } $d = $cabecera['delimitador']; $i = $cabecera['indices']; $candidatosEstado = []; while (($fila = fgetcsv($stream, 0, $d)) !== false) { $entidad = $this->clave($fila[$i['entidad']] ?? '', 2); if ($entidad !== $claveEstado) { continue; } $mun = $i['municipio'] === null ? null : $this->clave($fila[$i['municipio']] ?? '', 3); $loc = $i['localidad'] === null ? null : $this->clave($fila[$i['localidad']] ?? '', 4); $metricas = $this->metricas( $this->entero($fila[$i['p15']] ?? null), $this->entero($fila[$i['secundaria']] ?? null) ); if (!$this->metricasValidas($metricas)) { continue; } $registro = [ 'nombre' => $i['nombre_entidad'] === null ? '' : trim((string)($fila[$i['nombre_entidad']] ?? '')), 'metricas' => $metricas ]; if (($mun === null || $mun === '000') && ($loc === null || $loc === '0000')) { return $this->exito($candidato, $origen, $claveEstado, $registro['nombre'], $metricas); } if ($mun === null && $loc === null) { $candidatosEstado[] = $registro; } } if (count($candidatosEstado) === 1) { $r = $candidatosEstado[0]; return $this->exito($candidato, $origen, $claveEstado, $r['nombre'], $r['metricas']); } return $this->error('La estructura es compatible, pero no se pudo identificar de forma inequívoca el total estatal.'); } private function buscarCabecera($stream): ?array { $delimitadores = [',', ';', "\t", '|']; for ($linea = 1; $linea <= self::MAX_LINEAS_CABECERA; $linea++) { $texto = fgets($stream); if ($texto === false) { break; } $texto = preg_replace('/^\xEF\xBB\xBF/', '', (string)$texto); if (trim($texto) === '') { continue; } foreach ($delimitadores as $d) { $campos = str_getcsv($texto, $d); if (count($campos) < 3) { continue; } $normal = array_map([$this, 'normalizar'], $campos); $indices = $this->indices($normal); if ($indices !== null) { return ['delimitador' => $d, 'indices' => $indices, 'linea' => $linea]; } } } return null; } private function indices(array $cabecera): ?array { $mapa = []; foreach ($cabecera as $idx => $nombre) { if ($nombre !== '') { $mapa[$nombre] = $idx; } } $entidad = $this->alias($mapa, ['ENTIDAD','ENT','CVE_ENT','CVE_ENTIDAD','CLAVE_ENTIDAD']); $p15 = $this->alias($mapa, ['P_15YMAS','P15YMAS','POB_15YMAS','POB15MAS']); $sec = $this->alias($mapa, ['P15SEC_CO','P_15SEC_CO','P15SEC_COMPLETA','SECUNDARIA_COMPLETA_15_MAS']); if ($entidad === null || $p15 === null || $sec === null) { return null; } return [ 'entidad' => $entidad, 'municipio' => $this->alias($mapa, ['MUN','MUNICIPIO','CVE_MUN','CVE_MUNICIPIO']), 'localidad' => $this->alias($mapa, ['LOC','LOCALIDAD','CVE_LOC','CVE_LOCALIDAD']), 'nombre_entidad' => $this->alias($mapa, ['NOM_ENT','NOMBRE_ENTIDAD','ENTIDAD_NOMBRE']), 'p15' => $p15, 'secundaria' => $sec ]; } private function metricas(?int $poblacion, ?int $secundaria): array { $pct = ($poblacion !== null && $poblacion > 0 && $secundaria !== null) ? round(($secundaria / $poblacion) * 100, 2) : null; return [ 'poblacion_15_mas' => $poblacion, 'secundaria_completa' => $secundaria, 'secundaria_completa_pct' => $pct ]; } private function metricasValidas(array $m): bool { $p = $m['poblacion_15_mas'] ?? null; $s = $m['secundaria_completa'] ?? null; $pct = $m['secundaria_completa_pct'] ?? null; return is_int($p) && $p > 0 && is_int($s) && $s >= 0 && $s <= $p && is_numeric($pct) && $pct >= 0 && $pct <= 100; } private function exito(array $candidato, string $origen, string $clave, string $nombre, array $metricas): array { return [ 'ok' => true, 'fuente' => (string)$candidato['fuente'], 'periodo' => (string)$candidato['periodo'], 'producto' => (string)$candidato['producto'], 'archivo_origen' => $origen, 'compatibilidad' => 'VALIDADA', 'estado' => ['clave' => $clave, 'nombre' => $nombre, 'metricas' => $metricas], 'municipios' => [], 'municipios_total' => 0, 'generado_at' => date('Y-m-d H:i:s') ]; } private function entero($valor): ?int { $v = str_replace([',',' '], '', trim((string)$valor)); if ($v === '' || $v === '*' || !preg_match('/^\d+(?:\.0+)?$/', $v)) { return null; } return (int)$v; } private function clave($valor, int $longitud): ?string { $v = trim((string)$valor); if ($v === '' || !preg_match('/^\d+(?:\.0+)?$/', $v)) { return null; } return str_pad((string)(int)$v, $longitud, '0', STR_PAD_LEFT); } private function alias(array $mapa, array $nombres): ?int { foreach ($nombres as $nombre) { if (array_key_exists($nombre, $mapa)) { return (int)$mapa[$nombre]; } } return null; } private function normalizar($valor): string { $v = preg_replace('/^\xEF\xBB\xBF/', '', (string)$valor); $v = strtoupper(trim($v)); $v = str_replace(['Á','É','Í','Ó','Ú','Ü','Ñ'], ['A','E','I','O','U','U','N'], $v); $v = preg_replace('/[^A-Z0-9_]+/', '_', $v) ?? $v; return trim(preg_replace('/_+/', '_', $v) ?? $v, '_'); } private function normalizarRegistro(array $registro): array { $salida = []; foreach ($registro as $k => $v) { $salida[$this->normalizar($k)] = $v; } return $salida; } private function descubrirIntercensal2025(string $claveEstado): array { if ((int)date('Y') < 2026) { return []; } if ($this->enlacesIntercensal2025 === null) { $this->enlacesIntercensal2025 = []; foreach (['https://www.inegi.org.mx/programas/intercensal/2025/', 'https://www.inegi.org.mx/programas/eic/2025/'] as $pagina) { $html = $this->getTexto($pagina); if ($html === null || !preg_match_all('/href\s*=\s*["\']([^"\']+)["\']/iu', $html, $m)) { continue; } foreach ($m[1] as $href) { $url = $this->urlAbsoluta((string)$href, $pagina); if ($url === null || !$this->urlInegi($url)) { continue; } $path = strtolower((string)parse_url($url, PHP_URL_PATH)); if (preg_match('/\.(zip|csv)$/', $path) && strpos(strtolower($url), '2025') !== false) { $this->enlacesIntercensal2025[$url] = $url; } } } $this->enlacesIntercensal2025 = array_values($this->enlacesIntercensal2025); } $slug = $this->slugEstado($claveEstado); $resultado = []; foreach ($this->enlacesIntercensal2025 as $url) { $n = strtolower(rawurldecode($url)); $n = str_replace(['á','é','í','ó','ú','ü','ñ'], ['a','e','i','o','u','u','n'], $n); $coincideClave = preg_match('/(?:^|[^0-9])' . preg_quote($claveEstado, '/') . '(?:[^0-9]|$)/', $n); if ($coincideClave || ($slug !== '' && strpos(preg_replace('/[^a-z0-9]+/', '_', $n), $slug) !== false) || strpos($n, 'nacional') !== false) { $resultado[] = $url; } } return array_values(array_unique($resultado)); } private function getTexto(string $url): ?string { if (!function_exists('curl_init') || !$this->urlInegi($url)) { return null; } $ch = curl_init(); curl_setopt_array($ch, [ CURLOPT_URL => $url, CURLOPT_RETURNTRANSFER => true, CURLOPT_FOLLOWLOCATION => true, CURLOPT_MAXREDIRS => 3, CURLOPT_CONNECTTIMEOUT => 5, CURLOPT_TIMEOUT => 10, CURLOPT_SSL_VERIFYPEER => true, CURLOPT_USERAGENT => 'SistemaComercialIMPE/1.0' ]); $contenido = curl_exec($ch); $http = (int)curl_getinfo($ch, CURLINFO_HTTP_CODE); $error = curl_error($ch); unset($ch); return is_string($contenido) && $error === '' && $http >= 200 && $http < 400 ? $contenido : null; } private function getJson(string $url): ?array { $texto = $this->getTexto($url); $datos = $texto !== null ? json_decode($texto, true) : null; return is_array($datos) ? $datos : null; } private function urlAbsoluta(string $href, string $base): ?string { $href = trim($href); if ($href === '') return null; if (preg_match('#^https?://#i', $href)) return $href; if (strpos($href, '//') === 0) return 'https:' . $href; if (strpos($href, '/') === 0) return 'https://www.inegi.org.mx' . $href; $p = parse_url($base); if (!is_array($p) || empty($p['host'])) return null; $dir = rtrim(str_replace('\\', '/', dirname($p['path'] ?? '/')), '/'); return ($p['scheme'] ?? 'https') . '://' . $p['host'] . ($dir !== '' ? $dir : '') . '/' . ltrim($href, '/'); } private function urlInegi(string $url): bool { $host = strtolower((string)parse_url($url, PHP_URL_HOST)); return $host === 'inegi.org.mx' || substr($host, -13) === '.inegi.org.mx'; } private function rutaCache(string $clave, string $id): string { $id = preg_replace('/[^A-Za-z0-9_-]+/', '_', $id); return ROOT_PATH . '/storage/cache/inegi/educacion_objetivo_' . $id . '_' . $clave . '.json'; } private function leerCache(string $ruta): ?array { if (!is_file($ruta)) return null; $mtime = filemtime($ruta); if ($mtime === false || time() - $mtime > self::CACHE_TTL_SEGUNDOS) return null; $datos = json_decode((string)@file_get_contents($ruta), true); return is_array($datos) && ($datos['ok'] ?? false) === true ? $datos : null; } private function guardarCache(string $ruta, array $datos): void { $dir = dirname($ruta); if (!is_dir($dir)) @mkdir($dir, 0775, true); @file_put_contents($ruta, json_encode($datos, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT), LOCK_EX); } private function slugEstado(string $clave): string { $e = [ '01'=>'aguascalientes','02'=>'baja_california','03'=>'baja_california_sur','04'=>'campeche','05'=>'coahuila','06'=>'colima', '07'=>'chiapas','08'=>'chihuahua','09'=>'ciudad_de_mexico','10'=>'durango','11'=>'guanajuato','12'=>'guerrero','13'=>'hidalgo', '14'=>'jalisco','15'=>'mexico','16'=>'michoacan','17'=>'morelos','18'=>'nayarit','19'=>'nuevo_leon','20'=>'oaxaca','21'=>'puebla', '22'=>'queretaro','23'=>'quintana_roo','24'=>'san_luis_potosi','25'=>'sinaloa','26'=>'sonora','27'=>'tabasco','28'=>'tamaulipas', '29'=>'tlaxcala','30'=>'veracruz','31'=>'yucatan','32'=>'zacatecas' ]; return $e[$clave] ?? ''; } private function error(string $mensaje): array { return ['ok'=>false,'mensaje'=>$mensaje,'fuente'=>'','periodo'=>'','producto'=>'','archivo_ori